  ensures v2 as int == new_ptr as int + expected_delay.to_int(), v2@.provenance == new_ptr@.provenance,
{
    proof {
        let v = v as usize;
        assert((v & 3) == (v % 4)) by(bit_vector);
        let u = new_ptr as usize;
        assert(u % 4 == 0usize ==> ((v&3) | u) == add(v&3, u)) by(bit_vector);
